import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

const observeRejection = async (thrownValue: unknown) => {
  let observedError: Error | undefined;
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield -- rejects before yielding chunks to exercise the catch path
    async *sendMessage() {
      throw thrownValue;
    },
    generateStructured: <T>() => Promise.resolve({} as T),
  };
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test.'}), undefined, {
    hooks: {
      onError: async (_session, error) => {
        observedError = error;
      },
    },
  });
  const session: ChatSession = {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content: 'hi', timestamp: SENT_AT}],
  };
  const rethrown = await orchestrator.processMessage(session).then(
    () => Symbol('resolved'),
    (caught: unknown) => caught
  );
  return {
    observedError,
    isError: observedError instanceof Error,
    message: observedError?.message,
    cause: observedError?.cause,
    hasCauseKey: observedError !== undefined ? Object.hasOwn(observedError, 'cause') : false,
    rethrown,
  };
};

describe('onError rejection coercion', () => {
  it('wraps arbitrary rejections with cause while passing Error instances through unchanged', async () => {
    const plainObject = {code: 503, detail: 'upstream down'};
    const existingError = new Error('already an error');

    const [fromString, fromObject, fromVoid, fromError] = await Promise.all([
      observeRejection('string boom'),
      observeRejection(plainObject),
      observeRejection(undefined),
      observeRejection(existingError),
    ]);

    expect({
      stringCase: {
        isError: fromString.isError,
        message: fromString.message,
        cause: fromString.cause,
        rethrown: fromString.rethrown,
      },
      objectCase: {
        isError: fromObject.isError,
        mentionsDetail: Boolean(fromObject.message?.includes('upstream down')),
        cause: fromObject.cause,
        rethrown: fromObject.rethrown,
      },
      voidCase: {
        isError: fromVoid.isError,
        message: fromVoid.message,
        hasCauseKey: fromVoid.hasCauseKey,
        cause: fromVoid.cause,
        rethrown: fromVoid.rethrown,
      },
      errorCase: {
        sameInstance: fromError.observedError === existingError,
        hasCauseKey: fromError.hasCauseKey,
        rethrown: fromError.rethrown,
      },
    }).toEqual({
      stringCase: {
        isError: true,
        message: 'string boom',
        cause: 'string boom',
        rethrown: 'string boom',
      },
      objectCase: {
        isError: true,
        mentionsDetail: true,
        cause: plainObject,
        rethrown: plainObject,
      },
      voidCase: {
        isError: true,
        message: 'undefined',
        hasCauseKey: true,
        cause: undefined,
        rethrown: undefined,
      },
      errorCase: {
        sameInstance: true,
        hasCauseKey: false,
        rethrown: existingError,
      },
    });
  });
});

